window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cc35b16bf572acd4"]={"versions": [{"id": "FIG-cc35b16bf572acd4", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitätsdiagramm der AUTOSAR-Methodik (Work Breakdown Structure / Activity View) zur Spezifikation der Konfiguration des Non-Volatile Memory Managers (NvM) innerhalb der BSW-Konfigurationsphase auf ECU-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Rolle:\n<ul class=\"fig-list\"><li><code>ECU Integrator</code> [1]: Führt die Aktivität aus (<code>«performs»</code>).\n</li></ul>\n</li><li>Aktivität:\n<ul class=\"fig-list\"><li><code>Configure NvM</code>: Prozessschritt zur Konfiguration des NvM-Basissofwaredienstes.\n</li></ul>\n</li><li>Eingangsartefakte (<code>«input»</code>):\n<ul class=\"fig-list\"><li><code>BSW Module Delivered Bundle</code> [0..1]: Modulspezifische Lieferpakete (Dateien/Beschreibungen) des BSW-Herstellers.\n</li><li><code>ECU Extract</code> [1]: Systemextrakt der konkreten Steuergerätekonfiguration.\n</li><li><code>AUTOSAR Standardized ECU Configuration Parameter Definition</code> [0..1]: Standardisierte Parameterschablonen für BSW-Module.\n</li><li><code>Service Component Description</code> [0..*]: Schnittstellen- und Service-Port-Beschreibungen der Software-Komponenten bezüglich NVRAM-Zugriffen.\n</li></ul>\n</li><li>Ein-/Ausgangsartefakt (<code>«inoutput»</code>):\n<ul class=\"fig-list\"><li><code>ECU Configuration Values</code> [1]: Bestehende Steuergeräte-Konfigurationswerte, die im Rahmen der Aktivität gelesen und um NvM-spezifische Parameterwerte ergänzt bzw. aktualisiert werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>ECU Integrator</code> startet die Aktivität <code>Configure NvM</code>.\n</li><li>Als verbindliche Eingabe dient der <code>ECU Extract</code> (Kardinalität 1).\n</li><li>Optional fließen standardisierte Parameterdefinitionen (<code>AUTOSAR Standardized ECU Configuration Parameter Definition</code>, Kardinalität 0..1), herstellerspezifische Modulpakete (<code>BSW Module Delivered Bundle</code>, Kardinalität 0..1) sowie Null bis viele Dienstkomponentenbeschreibungen (<code>Service Component Description</code>, Kardinalität 0..*) ein.\n</li><li>Bestehende <code>ECU Configuration Values</code> (Kardinalität 1) werden eingelesen, bezüglich der Blockkonfigurationen, Mapping-Informationen und Treiber-Zuordnungen des NvM modifiziert bzw. erweitert und als aktualisierte <code>ECU Configuration Values</code> zurückgeschrieben (<code>«inoutput»</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Konfiguration des NvM setzt eine konsistente Abstimmung zwischen Applikationsanforderungen (Service-Ports via Service Component Descriptions) und BSW-Basisdefinitionen voraus. Bei der NvM-Konfiguration ist sicherzustellen, dass die IDs und Layouts der NVRAM-Blöcke exakt mit den Spezifikationen der persistenten Daten der SW-Cs und des System- bzw. ECU-Extrakts übereinstimmen. Das Artefakt <code>ECU Configuration Values</code> fungiert als zentraler, inkrementell befüllter Konfigurationsspeicher.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-85ce8a03b46c15b2", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitätsdiagramm der AUTOSAR-Methodik (Work Breakdown Structure / Activity View) zur Spezifikation der Konfiguration des Non-Volatile Memory Managers (NvM) innerhalb der BSW-Konfigurationsphase auf ECU-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Rolle:\n<ul class=\"fig-list\"><li><code>ECU Integrator</code> [1]: Führt die Aktivität aus (<code>«performs»</code>).\n</li></ul>\n</li><li>Aktivität:\n<ul class=\"fig-list\"><li><code>Configure NvM</code>: Prozessschritt zur Konfiguration des NvM-Basissofwaredienstes.\n</li></ul>\n</li><li>Eingangsartefakte (<code>«input»</code>):\n<ul class=\"fig-list\"><li><code>BSW Module Delivered Bundle</code> [0..1]: Modulspezifische Lieferpakete (Dateien/Beschreibungen) des BSW-Herstellers.\n</li><li><code>ECU Extract</code> [1]: Systemextrakt der konkreten Steuergerätekonfiguration.\n</li><li><code>AUTOSAR Standardized ECU Configuration Parameter Definition</code> [0..1]: Standardisierte Parameterschablonen für BSW-Module.\n</li><li><code>Service Component Description</code> [0..*]: Schnittstellen- und Service-Port-Beschreibungen der Software-Komponenten bezüglich NVRAM-Zugriffen.\n</li></ul>\n</li><li>Ein-/Ausgangsartefakt (<code>«inoutput»</code>):\n<ul class=\"fig-list\"><li><code>ECU Configuration Values</code> [1]: Bestehende Steuergeräte-Konfigurationswerte, die im Rahmen der Aktivität gelesen und um NvM-spezifische Parameterwerte ergänzt bzw. aktualisiert werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>ECU Integrator</code> startet die Aktivität <code>Configure NvM</code>.\n</li><li>Als verbindliche Eingabe dient der <code>ECU Extract</code> (Kardinalität 1).\n</li><li>Optional fließen standardisierte Parameterdefinitionen (<code>AUTOSAR Standardized ECU Configuration Parameter Definition</code>, Kardinalität 0..1), herstellerspezifische Modulpakete (<code>BSW Module Delivered Bundle</code>, Kardinalität 0..1) sowie Null bis viele Dienstkomponentenbeschreibungen (<code>Service Component Description</code>, Kardinalität 0..*) ein.\n</li><li>Bestehende <code>ECU Configuration Values</code> (Kardinalität 1) werden eingelesen, bezüglich der Blockkonfigurationen, Mapping-Informationen und Treiber-Zuordnungen des NvM modifiziert bzw. erweitert und als aktualisierte <code>ECU Configuration Values</code> zurückgeschrieben (<code>«inoutput»</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Konfiguration des NvM setzt eine konsistente Abstimmung zwischen Applikationsanforderungen (Service-Ports via Service Component Descriptions) und BSW-Basisdefinitionen voraus. Bei der NvM-Konfiguration ist sicherzustellen, dass die IDs und Layouts der NVRAM-Blöcke exakt mit den Spezifikationen der persistenten Daten der SW-Cs und des System- bzw. ECU-Extrakts übereinstimmen. Das Artefakt <code>ECU Configuration Values</code> fungiert als zentraler, inkrementell befüllter Konfigurationsspeicher.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-cc35b16bf572acd4", "to": "FIG-85ce8a03b46c15b2", "fr": "R4.0.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
